content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
    Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #f3f4f6;
  color: #1f2937;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  min-height: 100dvh;
}

.app-container {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 800px;
  height: 100vh;
  height: 100dvh;
  max-height: 900px;
  background-color: #ffffff;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  border-radius: 12px;
  overflow: hidden;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  background-color: #ffffff;
  border-bottom: 1px solid #e5e7eb;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #4f46e5;
}

.controls {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 12px 24px;
  background-color: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
}

.color-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  box-shadow: 0 0 0 2px #d1d5db;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.color-btn:hover {
  transform: scale(1.1);
}

.color-btn:active {
  transform: scale(0.95);
}

.color-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px #4f46e5, 0 0 0 5px #ffffff;
}

.color-btn.active {
  box-shadow: 0 0 0 3px #4f46e5;
}

.size-selector {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: #4b5563;
}

.size-slider {
  width: 100px;
  cursor: pointer;
}

.size-slider:focus-visible {
  outline: 2px solid #4f46e5;
  outline-offset: 2px;
}

.clear-btn {
  background-color: #ef4444;
  color: #ffffff;
  border: none;
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
  margin-left: auto;
}

.clear-btn:hover {
  background-color: #dc2626;
}

.clear-btn:active {
  transform: scale(0.98);
}

.clear-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.4);
}

.canvas-container {
  flex: 1;
  position: relative;
  overflow: hidden;
  background-color: #ffffff;
  touch-action: none;
}

.drawing-canvas {
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
}

@media (max-width: 640px) {
  .app-container {
    height: 100vh;
    height: 100dvh;
    max-height: none;
    border-radius: 0;
  }

  .controls {
    gap: 12px;
    padding: 10px 16px;
  }

  .clear-btn {
    margin-left: 0;
    width: 100%;
  }
}

import { useState, useRef, useEffect } from 'react';

const COLORS = [
  '#000000',
  '#ef4444',
  '#3b82f6',
  '#10b981',
  '#f59e0b',
  '#8b5cf6',
  '#ffffff',
];

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [color, setColor] = useState<string>('#000000');
  const [lineWidth, setLineWidth] = useState<number>(5);
  const [isDrawing, setIsDrawing] = useState<boolean>(false);
  const [isEraser, setIsEraser] = useState<boolean>(false);
  const [history, setHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState<number>(-1);
  const lastPosition = useRef<{ x: number; y: number }>({ x: 0, y: 0 });

  const saveHistory = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dataUrl = canvas.toDataURL();
    setHistory((prev) => {
      const newHistory = prev.slice(0, historyIndex + 1);
      return [...newHistory, dataUrl];
    });
    setHistoryIndex((prev) => prev + 1);
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const handleResize = () => {
      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;

      const tempCanvas = document.createElement('canvas');
      const tempCtx = tempCanvas.getContext('2d');
      tempCanvas.width = canvas.width;
      tempCanvas.height = canvas.height;
      if (tempCtx) {
        tempCtx.drawImage(canvas, 0, 0);
      }

      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;

      ctx.scale(dpr, dpr);

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, rect.width, rect.height);

      if (tempCtx) {
        ctx.drawImage(tempCanvas, 0, 0, tempCanvas.width, tempCanvas.height, 0, 0, rect.width, rect.height);
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    if (history.length === 0 && canvas) {
      // 初期状態を保存
      const dataUrl = canvas.toDataURL();
      setHistory([dataUrl]);
      setHistoryIndex(0);
    }

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  const restoreCanvas = (dataUrl: string) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.src = dataUrl;
    img.onload = () => {
      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, rect.width, rect.height);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height, 0, 0, rect.width, rect.height);
    };
  };

  const undo = () => {
    if (historyIndex <= 0) return;
    const newIndex = historyIndex - 1;
    setHistoryIndex(newIndex);
    restoreCanvas(history[newIndex]);
  };

  const redo = () => {
    if (historyIndex >= history.length - 1) return;
    const newIndex = historyIndex + 1;
    setHistoryIndex(newIndex);
    restoreCanvas(history[newIndex]);
  };

  const startDrawing = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setIsDrawing(true);
    lastPosition.current = { x, y };
  };

  const draw = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // 二次曲線による滑らかな補間描画
    const xc = (lastPosition.current.x + x) / 2;
    const yc = (lastPosition.current.y + y) / 2;

    ctx.beginPath();
    ctx.moveTo(lastPosition.current.x, lastPosition.current.y);
    ctx.quadraticCurveTo(lastPosition.current.x, lastPosition.current.y, xc, yc);
    ctx.strokeStyle = isEraser ? '#ffffff' : color;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();

    lastPosition.current = { x, y };
  };

  const stopDrawing = () => {
    if (isDrawing) {
      setIsDrawing(false);
      saveHistory();
    }
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, rect.width, rect.height);
    saveHistory();
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">お絵かきボード</h1>
      </header>

      <div className="controls">
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          {COLORS.map((c) => (
            <button
              key={c}
              className={`color-btn ${!isEraser && color === c ? 'active' : ''}`}
              style={{ backgroundColor: c }}
              onClick={() => {
                setColor(c);
                setIsEraser(false);
              }}
              aria-label={`色 ${c}`}
            />
          ))}
        </div>

        <button
          className="clear-btn"
          style={{ backgroundColor: isEraser ? '#4f46e5' : '#6b7280', marginLeft: 0 }}
          onClick={() => setIsEraser(!isEraser)}
        >
          {isEraser ? 'ペンモード' : '消しゴム'}
        </button>

        <button
          className="clear-btn"
          style={{ backgroundColor: '#6b7280', marginLeft: 0 }}
          onClick={undo}
          disabled={historyIndex <= 0}
        >
          元に戻す
        </button>

        <button
          className="clear-btn"
          style={{ backgroundColor: '#6b7280', marginLeft: 0 }}
          onClick={redo}
          disabled={historyIndex >= history.length - 1}
        >
          やり直し
        </button>

        <div className="size-selector">
          <label htmlFor="size-range">太さ: {lineWidth}px</label>
          <input
            id="size-range"
            type="range"
            min="1"
            max="50"
            value={lineWidth}
            onChange={(e) => setLineWidth(Number(e.target.value))}
            className="size-slider"
          />
        </div>

        <button className="clear-btn" onClick={clearCanvas}>
          全消去
        </button>
      </div>

      <div className="canvas-container">
        <canvas
          ref={canvasRef}
          className="drawing-canvas"
          onPointerDown={startDrawing}
          onPointerMove={draw}
          onPointerUp={stopDrawing}
          onPointerLeave={stopDrawing}
        />
      </div>
    </div>
  );
}
